import{_ as a,o as i,c as o,a2 as t}from"./chunks/framework.BN2sqjC1.js";const m=JSON.parse('{"title":"ADR-0026 — Revisione della shell UI desktop (M8)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0026-shell-ui-revisione.md","filePath":"adr/0026-shell-ui-revisione.md"}'),n={name:"adr/0026-shell-ui-revisione.md"};function r(s,e,l,d,c,p){return i(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="adr-0026-—-revisione-della-shell-ui-desktop-m8" tabindex="-1">ADR-0026 — Revisione della shell UI desktop (M8) <a class="header-anchor" href="#adr-0026-—-revisione-della-shell-ui-desktop-m8" aria-label="Permalink to &quot;ADR-0026 — Revisione della shell UI desktop (M8)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata</td></tr><tr><td><strong>Recepito in</strong></td><td><code>Specifications.md</code> v1.4 (2026-11-02): §2.2.1, §2.6.6, §4.2 (Appendice C.4)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-28</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§2.2.1 (<code>workspace</code>, <code>sidebar</code>, <code>statusbar</code>, <code>appearance</code>, <code>bookmarks</code>, <code>outline</code>), §4.2 (frontend); V-02/D-01, V-07/D-07, V-08/D-02, V-09/D-06; ADR-0004, ADR-0009, ADR-0016</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>sì (§2.2.1 riga <code>statusbar</code>; §4.2 elenco di <code>sidebar/</code>) → richiede aggiornamento di <code>Specifications.md</code> da parte dell&#39;owner</td></tr></tbody></table><p><strong>Aggiornamento 2026-11-02.</strong> La tab che qui si chiama sia «Segnalibri» sia «Link» è <em>Link</em> nel codice (link in uscita, backlink, bookmark). La barra di stato resta eliminata: la barra opzionale di ADR-0035 è ancora una <em>proposta</em> e non è implementata.</p><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>La shell attuale (<code>app/App.tsx</code>) ha una titlebar minimale, una sidebar sinistra con quattro tab (File, Ricerca, Tag, Segnalibri), una destra con tre (Struttura, Backlink, Proprietà) e una status bar che accumula toggle delle sidebar, statistiche dell&#39;editor, sync, permessi, aggiornamenti e inviti. Non esistono ribbon di comandi rapidi, selettore vault in-app, avatar o login nella shell, pannelli Tag/Statistiche/Slide, menu tab completo (blocco, chiudi a destra/sinistra/tutto) né un toggle tema rapido. Il mockup di progetto (28/10/2026) ridisegna la shell attorno a questi elementi.</p><p>Vincoli che restano validi: finestra singola Wails v2 (V-07), architettura chiusa senza temi o CSS personalizzati (V-02), nessuna funzione cross-vault (D-06), CSP <code>default-src &#39;self&#39;</code> (ADR-0005), niente accesso diretto a disco/rete dal frontend.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><p><strong>Disposizione.</strong> Header (toggle sidebar sinistra, pulsante ricerca, palette, switch chiaro/scuro, impostazioni, toggle sidebar destra; le tab restano nella barra di ciascun pane, sotto l&#39;header, perché con gli split ogni pane ha le sue) · ribbon verticale sempre visibile · sidebar sinistra · area editor con slot chat in basso · sidebar destra con footer di sync · footer sinistro con selettore vault, impostazioni e avatar/login.</p><p><strong>Ribbon.</strong> Nuova cartella, nuova nota, nuova lavagna, nuovo disegno, nuova base, separatore, esporta PDF, esporta come immagine. Ogni voce è un comando del registro (<code>commands/registry.ts</code>), quindi raggiungibile anche da palette e hotkey. «Separatore» inserisce <code>---</code> nella nota attiva (coerente con il delimitatore di ADR-0027).</p><p><strong>Sidebar sinistra:</strong> tab <em>File</em> e <em>Struttura</em> (outline). La ricerca diventa un pulsante in header che apre la vista di ricerca esistente; Tag e Segnalibri passano a destra.</p><p><strong>Sidebar destra:</strong> tab <em>Proprietà</em>, <em>Tag</em>, <em>Segnalibri</em> (link in uscita, backlink e bookmark del vault, ADR-0016), <em>ShowSlide</em> (ADR-0027), <em>Statistiche</em> (versioni, creazione, ultima modifica, autore, condivisione, parole, capitoli). Il footer mostra lo stato di sync del vault (§2.9), i permessi, l&#39;indicatore di aggiornamento e gli inviti.</p><p><strong>Status bar eliminata.</strong> Riga/colonna e conteggi dell&#39;editor confluiscono in <em>Statistiche</em>; lo stato di indicizzazione, i permessi, gli aggiornamenti, la sync e gli inviti nel footer della sidebar destra e, a sidebar chiusa, nell&#39;header (nessun indicatore sparisce con la sidebar). Le tab <em>Backlink</em> e <em>Segnalibri</em> diventano la tab <em>Link</em> (link in uscita, backlink, bookmark). Il requisito «Word count» (P0, <code>statusbar</code>) resta soddisfatto dal pannello.</p><p><strong>Tab.</strong> Campo opzionale <code>pinned</code> (blocco) in <code>workspace.json</code>; menu contestuale con Blocca/Sblocca, Chiudi, Chiudi a destra, Chiudi a sinistra, Chiudi altre, Chiudi tutto. Le chiusure di massa non toccano i tab bloccati. Il campo è retrocompatibile: i file senza <code>pinned</code> si leggono invariati.</p><p><strong>Footer sinistro.</strong> Nome del vault e numero di note; il click apre l&#39;elenco dei vault recenti e «Apri cartella…» (cambio vault senza passare dalla Welcome). Pulsante impostazioni; con sessione cloud attiva l&#39;avatar dell&#39;utente (menu account/dispositivi/esci), altrimenti un pulsante «Accedi» (OIDC come da D-08, nessuna credenziale nell&#39;app).</p><p><strong>Tema.</strong> Il pulsante in header alterna chiaro/scuro; <code>system</code> resta selezionabile nelle impostazioni. Restano solo i temi integrati (V-02).</p><p><strong>Chat ACP.</strong> Solo uno slot UI disabilitato sotto l&#39;editor, dietro la feature <code>chat</code> del Config Profile, spenta per default (a differenza delle altre feature, un flag mancante vale «spento»). Nessun codice di protocollo: l&#39;integrazione ACP richiede un ADR dedicato (client Go, sicurezza, perimetro di rete V-01).</p><p><strong>Persistenza.</strong> I valori legacy di <code>left.tab</code>/<code>right.tab</code> in <code>workspace.json</code> vengono mappati ai nuovi tab (<code>search</code>, <code>tags</code>, <code>bookmarks</code> → <code>files</code>; <code>outline</code> a destra → <code>properties</code>), senza perdere layout né tab aperti.</p><p><strong>Implementazione.</strong> Prima una scomposizione senza cambi funzionali di <code>App.tsx</code> in componenti in <code>src/shell/</code> (M8-WP1), con i test esistenti come rete di sicurezza; poi le modifiche visive e funzionali per work package.</p><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Mantenere status bar e aggiungere solo il ribbon</strong> — scartata: lascia lo stato di sync e le statistiche in una barra affollata e non offre lo spazio per i nuovi pannelli.</li><li><strong>Ricerca come tab permanente della sidebar</strong> — scartata: il mockup la porta in header, e la ricerca di vault resta comunque un comando (<code>search:vault</code>).</li><li><strong>Selettore vault con apertura di una seconda finestra</strong> — scartata: Wails v2 supporta una sola finestra per processo (V-07).</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><ul><li>La shell guadagna punti d&#39;accesso rapidi senza nuove dipendenze; ogni azione resta un comando del registro.</li><li>Cambiano posizione e chiavi dei tab: le scorciatoie <code>sidebar:*</code> e le chiavi i18n vanno riviste; gli e2e <code>a11y</code> e <code>keyboard</code> vanno aggiornati.</li><li>Il cambio vault in-app richiede di salvare il layout e azzerare lo store prima dell&#39;apertura.</li><li>Proposte di modifica allo spec: aggiornare la riga <code>statusbar</code> di §2.2.1 (il word count vive nel pannello Statistiche) e l&#39;elenco di <code>sidebar/</code> in §4.2.</li></ul>',22)])])}const g=a(n,[["render",r]]);export{m as __pageData,g as default};
